command:
(until apk add --no-cache postgresql-client >/tmp/apk.log 2>&1; do sleep 3; done) &
cat > /srv.py <<'PY'
import json, os, subprocess, threading, time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

SHA = os.environ.get("RELEASE_SHA", "unset")
URL = os.environ.get("DATABASE_URL", "")


def psql(sql):
    r = subprocess.run(["psql", URL, "-tAc", sql], capture_output=True, text=True, timeout=10)
    return r.returncode == 0, r.stdout.strip()


def boot():
    while True:
        try:
            ok, _ = psql("create table if not exists boots(id serial primary key, build_sha text, booted_at timestamptz default now()); insert into boots(build_sha) values ('%s')" % SHA)
            if ok:
                return
        except Exception:
            pass
        time.sleep(3)


threading.Thread(target=boot, daemon=True).start()


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def reply(self, code, body):
        b = body.encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(b)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        p = self.path.split("?")[0]
        if p == "/version":
            self.reply(200, json.dumps({"buildSha": SHA}))
        elif p == "/readyz":
            try:
                ok, _ = psql("select 1")
            except Exception:
                ok = False
            self.reply(200 if ok else 503, json.dumps({"status": "ok" if ok else "db_unreachable"}))
        elif p == "/data":
            try:
                ok, out = psql("select coalesce(json_agg(b order by id),'[]') from boots b")
            except Exception:
                ok, out = False, "[]"
            self.reply(200 if ok else 503, out or "[]")
        elif p == "/diag":
            try:
                log = open("/tmp/apk.log").read()[-400:]
            except Exception:
                log = ""
            self.reply(200, json.dumps({"apk": log, "psql": os.path.exists("/usr/bin/psql")}))
        else:
            self.reply(404, '{"error":"not_found"}')


ThreadingHTTPServer(("0.0.0.0", 8080), H).serve_forever()
PY
exec python3 -u /srv.py
